    try (Scanner sc = new Scanner(System.in);) {
        int n = Integer.parseInt(sc.next());
        int m = Integer.parseInt(sc.next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(sc.next());

        List<List<Integer>> g = new ArrayList<List<Integer>>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<Integer>());
        for (int i = 0; i < m; i++) {
            int u = Integer.parseInt(sc.next());
            int v = Integer.parseInt(sc.next());
            u--;
            v--;
            g.get(u).add(v);
            g.get(v).add(u);
        }

        int[] score = new int[n];
        boolean[] used = new boolean[n];
        Arrays.fill(score, 0);
        score[0] = 1;
        PriorityQueue<Integer[]> pq = new PriorityQueue<Integer[]>((u, v) -> {
            if (Integer.compare(u[0], v[0]) == 0) {
                return Integer.compare(v[1], u[1]);
            }
            return Integer.compare(u[0], v[0]);
        });
        pq.add(new Integer[]{a[0], -score[0], 0});
        while (!pq.isEmpty()) {
            int v = pq.peek()[2];
            pq.poll();
            if (used[v]) continue;
            used[v] = true;
            for (int to : g.get(v)) {
                if (a[v] <= a[to]) {
                    score[to] = Math.max(score[to], score[v] + (a[v] != a[to] ? 1 : 0));
                    pq.add(new Integer[]{a[to], -score[to], to});
                }
            }
        }

        System.out.println(Math.max(score[n - 1], 0));
    }
}

